(()=>{
'use strict';
const dialog=$('photoSearchDialog'),input=$('watchPhotoFile'),preview=$('watchPhotoPreview'),run=$('runPhotoSearch'),message=$('photoSearchMessage');let selected=null,objectUrl='',token=0,indexPromise,quickCache,lastError='';
const t=s=>window.JXI18n?.translate(s)||s;
function status(text){message.textContent=text;}
function resetBusy(){run.disabled=!selected;run.textContent='Find similar watches';run.removeAttribute('aria-busy');}
$('openPhotoSearch').onclick=()=>{status(selected?'Ready to compare your photo.':'First use may take a moment.');resetBusy();dialog.showModal()};
$('chooseWatchPhoto').onclick=()=>input.click();
input.addEventListener('change',async()=>{const file=input.files?.[0];if(!file)return;const request=++token;selected=null;resetBusy();preview.hidden=true;if(file.size>12*1024*1024){status('Choose an image smaller than 12 MB.');input.value='';return}if(!file.type.startsWith('image/')&&!/\.(jpe?g|png|webp|gif|bmp|avif|heic|heif)$/i.test(file.name)){status('Please choose an image file.');input.value='';return}if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl=URL.createObjectURL(file);try{const image=new Image();image.src=objectUrl;await image.decode();if(request!==token)return;if(image.naturalWidth<64||image.naturalHeight<64)throw Error('small');selected=image;preview.src=objectUrl;preview.hidden=false;status('Ready to compare your photo.');resetBusy()}catch{if(request===token){status('This image cannot be opened. Try a JPG or PNG.');input.value='';selected=null;resetBusy()}}});
async function deadline(promise){let timer;try{return await Promise.race([promise,new Promise((_,reject)=>{timer=setTimeout(()=>reject(Error('Timeout')),8000)})])}finally{clearTimeout(timer)}}
async function index(){if(!indexPromise)indexPromise=fetch('visual-index-20261114.json?v=1').then(r=>{if(!r.ok)throw Error('Index unavailable');return r.json()}).then(data=>data.rows.map(row=>({...row,features:row.vectors.map(JXVision.unpack)}))).catch(e=>{indexPromise=null;throw e});return indexPromise;}
function rankQuick(image){if(!quickCache)quickCache=(window.JXQuickIndex||[]).map(row=>({...row,features:row.views.map(JXVision.quickUnpack)}));if(!quickCache.length)throw Error('Quick index missing');const query=JXVision.quickExtract(image);if(!query.some(v=>v.edges.some(x=>x>1)))return[];return quickCache.map(row=>({code:row.id+'-'+row.color,score:JXVision.quickSimilarity(query,row.features)})).sort((a,b)=>b.score-a.score);}
async function rankModel(image){const [rows]=await Promise.all([index(),JXVision.load()]);const query=await JXVision.extract(image);return rows.map(row=>({code:row.id+'-'+row.color,score:JXVision.similarity(query,row.features)})).sort((a,b)=>b.score-a.score);}
run.onclick=async()=>{if(!selected)return;const request=++token;run.disabled=true;run.setAttribute('aria-busy','true');status('Comparing watches…');try{await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));const quick=rankQuick(selected);let ranked=quick;lastError='';try{const model=await deadline(rankModel(selected));if(model.length&&model[0].score>=.62)ranked=model;}catch(error){lastError=String(error&&error.message||error);}if(request!==token)return;const available=new Set(catalogEntries.map(e=>e.code));ranked=ranked.filter(row=>available.has(row.code)).slice(0,24);if(!ranked.length){status('No close visual matches found. Try a clearer front-facing photo.');resetBusy();return}photoMatches=new Map(ranked.map(row=>[row.code,row.score]));activeBrand=activeSeries=activeBand=activeColor='All';searchTerm='';currentPage=1;syncControls();$('photoQueryPreview').src=selected.src;$('photoResults').hidden=false;render();updateUrl();resetBusy();dialog.close();$('collection').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});}catch(error){lastError=String(error&&error.message||error);if(request!==token)return;status('This photo could not be compared. Try another photo or search by name.');resetBusy()}};
dialog.addEventListener('close',()=>{token++;resetBusy()});
$('clearPhotoResults').onclick=()=>{clearPhotoResults();currentPage=1;render();updateUrl()};
$('floatingSearch').onclick=()=>{const search=$('catalogSearch');search.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'start'});$('productSearch').focus({preventScroll:true})};
window.JXPhotoSearch={get active(){return !!photoMatches},get lastError(){return lastError},clear:clearPhotoResults};
})();
